-- Step 17: whether a company's prices already include sales tax.
--
-- One answer per company, given in the setup wizard by a company registered for sales tax. The
-- tax engine reads it: with prices that include the tax, the customer pays the price and the
-- tax is worked out of it; otherwise the tax is added on top. Companies set up before this
-- migration get "added on top", which is how nothing was ever worked before.
--
-- The statements are generated by drizzle-kit from src/modules/*/schema.ts; nothing is
-- hand-written. The table's grants and policies (drizzle/0010_setup.sql) cover the new column.
-- Reverse with drizzle/down/0015_prices_include_tax.sql.

ALTER TABLE "company_setup" ADD COLUMN "prices_include_tax" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "company_setup" ADD CONSTRAINT "company_setup_tax_in_price_only_when_registered" CHECK (not "company_setup"."prices_include_tax" or "company_setup"."sales_tax_registered");
